document.write('<script src="/layout.js"><\\/script>');

window.addEventListener('load', () => {
	[
		'https://fonts.googleapis.com/css?family=Noto Sans:400,700&display=swap',
		'https://www.kali.org/plugins/themify-icons/themify-icons.css'
	].forEach((href) => {
		const linkElement = document.createElement('link');
		linkElement.rel = 'stylesheet';
		linkElement.href = href;
		document.body.appendChild(linkElement);
	});
});

(() => {
	const toggles = $$('input[name=toggle-darkmode]');
	const toggleDarkMode = () => {
		const isDark = document.body.classList.toggle('dark-theme');
		toggles.forEach((toggle) => {
            toggle.checked = isDark;
        });
		return isDark;
	};

	toggles.forEach((toggle) => {
		toggle.onchange = () => {
			localStorage.setItem('darkmode', toggleDarkMode());
		};
	});

	if (localStorage.getItem('darkmode') === 'true') {
		toggleDarkMode();
	}

	const mediaQuery = window.matchMedia('(prefers-color-scheme:dark)');
	const syncFaviconAndTheme = () => {
		$$('.js-site-favicon').forEach((link) => {
			link.href = link.href
				.replace(/-dark/, '')
				.replace(/(\.\w+)$/, (mediaQuery.matches ? '-dark' : '') + '$1');
		});

		if (
			!localStorage.getItem('darkmode') &&
			mediaQuery.matches !== document.body.classList.contains('dark-theme')
		) {
			toggleDarkMode();
		}
	};

	mediaQuery.addListener(syncFaviconAndTheme);
	syncFaviconAndTheme();
})();

const attachMenuToggle = () => {
	const nav = document.querySelector('nav');
	if (!nav) {
		return false;
	}

	const button = nav.querySelector('button');
	if (!button) {
		return false;
	}

	button.addEventListener('click', () => {
		nav.classList.toggle('show-menu');
	});

	// Mobile dropdown toggle - click instead of hover
	const dropdowns = nav.querySelectorAll('.dropdown-menu');
	dropdowns.forEach((dropdown) => {
		const trigger = dropdown.querySelector('span');
		if (trigger) {
			trigger.addEventListener('click', (e) => {
				e.stopPropagation();
				// Close other dropdowns
				dropdowns.forEach((d) => {
					if (d !== dropdown) d.classList.remove('open');
				});
				dropdown.classList.toggle('open');
			});
		}
	});

	return true;
};

const initMenuToggle = () => {
	if (attachMenuToggle()) {
		return;
	}

	const observer = new MutationObserver(() => {
		if (attachMenuToggle()) {
			observer.disconnect();
		}
	});

	observer.observe(document.body, { childList: true, subtree: true });
};

if (document.readyState === 'loading') {
	document.addEventListener('DOMContentLoaded', initMenuToggle);
} else {
	initMenuToggle();
}
